function visual(p){
const n=projects.indexOf(p),txt=(x,y,t,c='')=>`<text x="${x}" y="${y}" class="${c}">${lang==='fa'?(faVisualWords[t]||(t.startsWith('SERVICE ')?'سرویس '+t.slice(8):t)):t}</text>`,box=(x,y,w,h,r=8)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}"/>`;
const scenes=[
// QA/QC intelligence: an original animated waveform feeding a scored quality gauge and coaching tiles.
`<g class="qc-wave">${Array.from({length:24},(_,i)=>`<line class="qc-bar" x1="${70+i*10}" x2="${70+i*10}" y1="${120-(8+(i*19%57))/2}" y2="${120+(8+(i*19%57))/2}" style="--phase:${i*.055}s"/>`).join('')}</g><path class="flow-path" d="M308 120H357"/><g class="qc-gauge"><circle class="qc-ring" cx="420" cy="119" r="56"/><circle class="qc-progress" cx="420" cy="119" r="56" transform="rotate(-90 420 119)"/>${txt(420,115,'QA / QC')}${txt(420,135,'KNOWLEDGE-LED','micro')}</g><g class="qc-report">${[62,98,134].map((y,i)=>`<rect x="510" y="${y}" width="${45+i*10}" height="20" rx="4"/><path d="M518 ${y+10}h${18+i*9}"/>`).join('')}</g>${txt(179,188,'CALLS · CHATS','micro')}${txt(420,207,'SCORE & COACH','micro')}`,
// Intelligence: distributed signals converge into a structured core and actionable outputs.
`<g class="signals">${[65,115,165].map((y,i)=>`<g class="signal s${i}">${box(52,y,65,24)}<path d="M64 ${y+12}h40"/></g><path class="flow-path" d="M117 ${y+12}C180 ${y+12} 170 120 234 120"/>`).join('')}</g><g class="core">${box(234,80,115,80,18)}${txt(291,113,'CONTEXT')}${txt(291,139,'→ INSIGHT','micro')}</g><path class="flow-path" d="M349 120H430"/><g class="action-stack">${[82,115,148].map((y,i)=>`${box(430,y,115,25)}${txt(487,y+17,['PRIORITIZE','FOLLOW UP','LEARN'][i],'micro')}`).join('')}</g>`,
// Credit journey: orbital stages, with a continuous path rather than repeated generic boxes.
`<path class="journey-line flow-path" d="M80 150C150 150 155 85 230 85S355 165 420 145S475 85 520 85"/>${[[80,150,'01','ELIGIBILITY'],[230,85,'02','PURCHASE'],[420,145,'03','REPAYMENT']].map(([x,y,a,b])=>`<circle class="pulse-dot" cx="${x}" cy="${y}" r="24"/>${txt(x,y+5,a)}${txt(x,y+48,b,'micro')}`).join('')}<circle class="traveler" r="5" cx="520" cy="85"/>`,
// CRM: a decision tree from a customer signal to owned action.
`${box(43,98,100,44)}${txt(93,125,'SIGNAL')}<path class="tree-link flow-path" d="M143 120H235M280 120H340V70H415M340 120V173H415"/><path class="decision" d="M235 120l23-23 23 23-23 23Z"/>${box(415,48,125,44)}${box(415,151,125,44)}${txt(477,75,'RESOLVE')}${txt(477,178,'ESCALATE')}<circle class="pulse-dot" cx="340" cy="120" r="5"/>`,
// Marketplace: catalog tiles converge on one fulfilment route.
`<g class="catalog-tiles">${[[60,65],[110,65],[60,115],[110,115]].map(([x,y],i)=>`<rect class="tile tile-${i}" x="${x}" y="${y}" width="37" height="37" rx="5"/>`).join('')}</g>${txt(103,191,'CATALOG','micro')}<path class="flow-path" d="M160 108H260M315 108H420"/><g class="market-hub">${box(260,78,55,60)}<path d="M270 91h35l-4 24h-25Z"/><circle cx="279" cy="126" r="3"/><circle cx="298" cy="126" r="3"/></g><g class="delivery">${box(420,86,73,43)}<path d="M493 98h20l22 18v13h-42Z"/><circle cx="440" cy="135" r="9"/><circle cx="515" cy="135" r="9"/></g>${txt(477,177,'FULFILLMENT','micro')}`,
// Analytics: an abstract dashboard, without business values or organizational data.
`<g class="dashboard-frame">${box(85,40,430,155,12)}<path d="M85 66H515"/><circle cx="100" cy="53" r="2"/><circle cx="110" cy="53" r="2"/><circle cx="120" cy="53" r="2"/></g><g class="chart-columns">${[44,64,51,83,95].map((h,i)=>`<rect class="chart-col col-${i}" x="${122+i*37}" y="${174-h}" width="21" height="${h}" rx="2"/>`).join('')}</g><circle class="chart-ring" cx="420" cy="124" r="36"/><path class="chart-trend flow-path" d="M343 164l32-25 28 8 30-31 30-23"/>`,
// Delivery: a release pipeline with quality gates.
`<path class="pipeline" d="M70 120H530"/>${[[90,'DEFINE'],[230,'BUILD'],[370,'TEST'],[510,'RELEASE']].map(([x,t],i)=>`<g class="gate gate-${i}"><path d="M${x} 92l28 28-28 28-28-28Z"/>${txt(x,125,['◇','⌘','✓','↗'][i])}${txt(x,182,t,'micro')}</g>`).join('')}<path class="flow-path" d="M90 120H510"/>`,
// Automation: a true loop with three operating steps and a stable core.
`<g class="automation-wheel"><circle cx="300" cy="120" r="78"/><path class="flow-path" d="M300 42a78 78 0 1 1-1 0"/><circle cx="300" cy="42" r="7"/><circle cx="368" cy="159" r="7"/><circle cx="232" cy="159" r="7"/></g>${txt(300,116,'AUTOMATE')}${txt(300,138,'REPEAT · REFINE','micro')}${txt(130,75,'STANDARDIZE','micro')}${txt(470,75,'MEASURE','micro')}${txt(300,221,'SCALE','micro')}`,
// Back-office: independent provider lanes join one operational workspace.
`${[55,108,161].map((y,i)=>`${box(55,y,100,32)}${txt(105,y+21,'SERVICE '+String.fromCharCode(65+i),'micro')}<path class="flow-path lane-${i}" d="M155 ${y+16}H220V124H290"/>`).join('')}<g class="workspace">${box(290,58,245,128,12)}<path d="M290 85H535M353 85V186"/>${[105,133,161].map(y=>`<path d="M369 ${y}H510"/><circle class="pulse-dot" cx="325" cy="${y}" r="4"/>`).join('')}${txt(413,76,'ONE WORKSPACE','micro')}</g>`
];
return `<svg class="concept-scene scene-${n}" viewBox="0 0 600 240" aria-hidden="true" focusable="false">${scenes[n]}</svg>`;
}
