const dialog=document.querySelector('#case');document.querySelector('#projects').onclick=e=>{const b=e.target.closest('[data-project]');if(!b)return;const p=projects[Number(b.dataset.project)];document.querySelector('#case-content').innerHTML=`<p class="eyebrow">${brand(p)} / ${projectLabel(p)}</p><h2>${p.title[lang]}</h2><p>${p.desc[lang]}</p><h3>${lang==='en'?'The challenge':'مسئله'}</h3><p>${p.problem[lang]}</p><h3>${lang==='en'?'My role & approach':'نقش و رویکرد من'}</h3><p>${p.approach[lang]}</p><h3>${lang==='en'?'Deliverables & scope':'خروجی‌ها و محدوده کار'}</h3><ul>${p.outputs[lang].map(o=>`<li>${o}</li>`).join('')}</ul><div class="case-metric"><strong>${lang==='fa'?'پیشنهاد من برای سنجش نتیجه (نه نتیجه قطعی پروژه)':'How I would validate impact (not an achieved result)'}</strong><p>${caseLens[Number(b.dataset.project)][lang]}</p></div><div class="tags">${p.tags.map(t=>`<span>${word(t)}</span>`).join('')}</div><div class="case-actions"><a class="button gold" href="mailto:mrezasmvt@gmail.com?subject=${encodeURIComponent('Portfolio: '+p.title.en)}">${lang==='en'?'Let’s discuss this work ↗':'درباره این تجربه صحبت کنیم ↗'}</a><a class="button outline" href="../links/#contact">${lang==='en'?'Contact links ↗':'راه‌های ارتباطی ↗'}</a></div>`;dialog.showModal();document.body.style.overflow='hidden'};document.querySelector('#close-case').onclick=()=>dialog.close();dialog.addEventListener('close',()=>document.body.style.overflow='');dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
